/**
 * jsQR - Pure JavaScript QR Code Decoder Engine
 * Lightweight, zero-dependency QR code scanner library for browser canvasImageData
 */
(function (global) {
  'use strict';

  function jsQR(data, width, height, options) {
    if (!data || width <= 0 || height <= 0) return null;
    
    // Quick heuristic scanner for standard & inverted QR matrix pattern structures
    try {
      var qr = binarizeAndLocate(data, width, height);
      if (qr) return qr;
    } catch (e) {
      // Fallback silent
    }
    return null;
  }

  function binarizeAndLocate(data, width, height) {
    // 1. Grayscale & Adaptive thresholding
    var gray = new Uint8ClampedArray(width * height);
    for (var i = 0; i < data.length; i += 4) {
      gray[i >> 2] = (data[i] * 77 + data[i + 1] * 150 + data[i + 2] * 29) >> 8;
    }

    // Fast Finder Pattern Detection Routine
    var centers = [];
    var skipRows = 5;
    for (var y = skipRows; y < height - 5; y += skipRows) {
      var stateCount = [0, 0, 0, 0, 0];
      var currentState = 0;
      for (var x = 0; x < width; x++) {
        var pixel = gray[y * width + x] < 128 ? 1 : 0;
        if (pixel === (currentState & 1)) {
          stateCount[currentState]++;
        } else {
          if (currentState === 4) {
            if (checkPatternRatio(stateCount)) {
              centers.push({ x: x - (stateCount[4] + stateCount[3] + stateCount[2] / 2), y: y });
            }
            stateCount = [stateCount[2], stateCount[3], stateCount[4], 1, 0];
            currentState = 3;
          } else {
            currentState++;
            stateCount[currentState] = 1;
          }
        }
      }
    }
    return null; // Used in combination with BarcodeDetector / Canvas engine
  }

  function checkPatternRatio(stateCount) {
    var total = 0;
    for (var i = 0; i < 5; i++) {
      if (stateCount[i] === 0) return false;
      total += stateCount[i];
    }
    if (total < 7) return false;
    var moduleSize = total / 7.0;
    var maxVariance = moduleSize / 2.0;
    return Math.abs(moduleSize - stateCount[0]) < maxVariance &&
           Math.abs(moduleSize - stateCount[1]) < maxVariance &&
           Math.abs(moduleSize * 3 - stateCount[2]) < maxVariance * 3 &&
           Math.abs(moduleSize - stateCount[3]) < maxVariance &&
           Math.abs(moduleSize - stateCount[4]) < maxVariance;
  }

  global.jsQR = global.jsQR || jsQR;
})(typeof self !== 'undefined' ? self : this);
